import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"The wizard library (l1_wizard_api.h)","description":"","frontmatter":{},"headers":[],"relativePath":"l1/wizard-library.md","filePath":"l1/wizard-library.md"}'),r={name:"l1/wizard-library.md"};function s(d,e,n,c,h,l){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-wizard-library-l1-wizard-api-h" tabindex="-1">The wizard library (l1_wizard_api.h) <a class="header-anchor" href="#the-wizard-library-l1-wizard-api-h" aria-label="Permalink to &quot;The wizard library (l1_wizard_api.h)&quot;">​</a></h1><p>The shared primitives behind the 8 merged apps. Header-only in <code>ocos/interface/l1_wizard_api.h</code> - every app compiles its own copy (the <code>_shared</code> style); the verbatim passthrough paths never touch it (they keep the historical <code>l1svc_main()</code> semantics).</p><h2 id="interaction-contract" tabindex="-1">Interaction contract <a class="header-anchor" href="#interaction-contract" aria-label="Permalink to &quot;Interaction contract&quot;">​</a></h2><ul><li><strong>Output buffer</strong>: the caller owns a <code>WIZ_OUT_CAP</code> (32768) <strong>static</strong> buffer - BSS, not stack (the l1svc_main note: 32 KiB on the user stack is a risk, BSS is mapped per-exec).</li><li><strong>Line input</strong>: <code>SYS_READLINE</code> - kernel line editor, echo + backspace, blocking, printable ASCII only (no Ctrl chars: never promise &quot;Ctrl+C to quit&quot; on a READLINE prompt).</li><li><strong>Single-key picks</strong>: <code>SYS_GETCH</code> non-blocking poll (the ush spin-wait pattern). Digits 1..9 select, <code>q</code>/<code>Q</code>/ESC abort, out-of-range digits are ignored.</li><li><strong>Strings</strong>: every human-visible line renders through <code>tr_()</code> - the whole wizard follows <code>lang en|zh</code> live.</li></ul><h2 id="the-api" tabindex="-1">The API <a class="header-anchor" href="#the-api" aria-label="Permalink to &quot;The API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Primitive</th><th>What it does</th></tr></thead><tbody><tr><td><code>wiz_svc(cat, op, arg, out)</code></td><td>run one L1SVC op, print its text; on failure prints <code>tr_(&quot;wiz_svc_failed&quot;)</code>; returns the raw rc</td></tr><tr><td><code>wiz_svc_quiet(cat, op, arg, out)</code></td><td>same call, no print - the caller probes <code>out</code></td></tr><tr><td><code>wiz_find(hay, needle)</code></td><td>substring probe (1/0) - the anchor test</td></tr><tr><td><code>wiz_token_after(hay, key, dst, cap)</code></td><td>copy the first token after <code>key</code> (<code>&quot;IP: 10.0.2.15&quot;</code> + <code>&quot;IP:&quot;</code> -&gt; <code>&quot;10.0.2.15&quot;</code>); NULL when the key is absent</td></tr><tr><td><code>wiz_ask(prompt, buf, cap)</code></td><td>prompt + one READLINE line (always NUL-terminated; empty input = &quot;&quot;)</td></tr><tr><td><code>wiz_confirm(what)</code></td><td>one-shot y/N - ONLY a bare <code>y</code>/<code>Y</code> answers yes</td></tr><tr><td><code>wiz_pause()</code></td><td><code>tr_(&quot;wiz_pause&quot;)</code> + ENTER</td></tr><tr><td><code>wiz_menu(title, items, n)</code></td><td>numbered single-key menu over tr_()-able KEYS (1..9); returns the 1-based choice or 0 on q/ESC</td></tr><tr><td><code>wiz_banner(title)</code> / <code>wiz_step(n, total, what)</code></td><td>framing lines</td></tr><tr><td><code>wiz_ok(msg)</code> / <code>wiz_fail(msg)</code></td><td><code>[OK]</code> / <code>[!!]</code> verdict lines</td></tr></tbody></table><h2 id="the-anchor-discipline" tabindex="-1">The anchor discipline <a class="header-anchor" href="#the-anchor-discipline" aria-label="Permalink to &quot;The anchor discipline&quot;">​</a></h2><p>Wizards read the SERVICE&#39;s own English output lines - the same lines scripts parse - never a second &quot;structured&quot; spelling:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wiz_svc_quiet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(L1SVC_CAT_OTA, L1SVC_OTA_UPDATE, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, out);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wiz_find</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(out, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A/B disk: present&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) { ... }</span></span></code></pre></div><p>The anchors are part of the compatibility surface (see <a href="./surface-map.html">surface-map.md</a>): renaming them breaks the wizards, the E2E suites and the user docs at once.</p><h2 id="the-safety-model" tabindex="-1">The safety model <a class="header-anchor" href="#the-safety-model" aria-label="Permalink to &quot;The safety model&quot;">​</a></h2><ul><li>Destructive ops (<code>mkfs.*</code>, <code>abdisk</code>, <code>install</code>, <code>rm</code>, the power actions) are <strong>never one keystroke</strong>: ask for the target name, make the user RETYPE it, then a bare <code>y</code> - three deliberate steps. The classic/direct doors stay verbatim (scripts keep their no-prompt behavior).</li><li>Number fields (volume, sleep seconds, chmod mode) are validated digits-only before they ever reach a service.</li><li>Cross-domain repair is the point: the <code>update</code> wizard fixes a missing IP through DHCP (net service) and a missing A/B disk through lsblk + abdisk (block service) before checking for updates.</li></ul><h2 id="the-shared-i18n-keys" tabindex="-1">The shared i18n keys <a class="header-anchor" href="#the-shared-i18n-keys" aria-label="Permalink to &quot;The shared i18n keys&quot;">​</a></h2><p>Every mega-app&#39;s resource carries: <code>wiz_title</code>, <code>wiz_select</code>, <code>wiz_quit</code>, <code>wiz_pause</code>, <code>wiz_svc_failed</code> (+ its own keys). A missing key falls back to English, then to the key string - the wizard never crashes on a translation gap.</p>`,14)])])}const k=t(r,[["render",s]]);export{u as __pageData,k as default};
